insert into public.app_config (kunci, nilai) values ('seed_anchor', to_jsonb(now()))
on conflict (kunci) do update set nilai = excluded.nilai;

-- Cek akhir: jumlah harus persis (email/kode_wilayah yang tidak ditemukan membuat baris hilang).
do $$
declare n int;
begin
  select count(*) into n from seed.reports;        if n <> 900 then raise exception 'seed.reports % baris, harus 900 (akun warga / regions kurang?)', n; end if;
  select count(*) into n from seed.report_updates; if n <> 3011 then raise exception 'seed.report_updates % baris, harus 3011', n; end if;
  select count(*) into n from seed.report_updates where admin_id is null;
  if n <> 924 then raise exception 'report_updates tanpa admin % baris, harus 924 (akun admin instansi kurang?)', n; end if;
  select count(*) into n from seed.upvotes;        if n <> 2167 then raise exception 'seed.upvotes % baris, harus 2167', n; end if;
  select count(*) into n from seed.ratings;        if n <> 338 then raise exception 'seed.ratings % baris, harus 338', n; end if;
end $$;
